export type TicketStatus="OPEN"|"IN_PROGRESS"|"CLOSED";
export type Priority="LOW"|"MEDIUM"|"HIGH"|"CRITICAL";
export type Ticket=Readonly<{id:number;title:string;status:TicketStatus;priority:Priority;tags:readonly string[];assignee:string|null}>;
export const STATUS_OPTIONS=[{value:"ALL",label:"Wszystkie"},{value:"OPEN",label:"Otwarte"},{value:"IN_PROGRESS",label:"W toku"},{value:"CLOSED",label:"Zamknięte"}] as const satisfies readonly {value:TicketStatus|"ALL";label:string}[];
export type StatusFilter=(typeof STATUS_OPTIONS)[number]["value"];
export function isStatusFilter(value:string):value is StatusFilter{return STATUS_OPTIONS.some(option=>option.value===value);}
export function matchesQuery(ticket:Ticket,query:string):boolean{const q=query.trim().toLowerCase();if(q==="")return true;return ticket.title.toLowerCase().includes(q)||ticket.tags.some(tag=>tag.toLowerCase().includes(q))||(ticket.assignee??"").toLowerCase().includes(q);}
export function filterTickets(tickets:readonly Ticket[],query:string,status:StatusFilter):Ticket[]{return tickets.filter(ticket=>(status==="ALL"||ticket.status===status)&&matchesQuery(ticket,query));}
export function summarize(tickets:readonly Ticket[]){return {total:tickets.length,open:tickets.filter(ticket=>ticket.status==="OPEN").length,urgent:tickets.filter(ticket=>ticket.status!=="CLOSED"&&(ticket.priority==="HIGH"||ticket.priority==="CRITICAL")).length};}

