export function summarize(tickets:readonly Ticket[]){return {total:tickets.length,open:tickets.filter(ticket=>ticket.status==="OPEN").length,urgent:tickets.filter(ticket=>ticket.status!=="CLOSED"&&(ticket.priority==="HIGH"||ticket.priority==="CRITICAL")).length};}
